// =========================================================================
// FACULTY WORKSPACE
// =========================================================================

function switchFacultyTab(tabName) {
  activeFacultyTab = tabName;
  document.querySelectorAll('#faculty-section .seg-tab').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.ftab === tabName);
  });

  document.querySelectorAll('#faculty-section .tab-pane-full').forEach(panel => {
    panel.style.display = 'none';
  });

  const target = document.getElementById(`faculty-tab-${tabName}`);
  if (target) target.style.display = 'block';

  if (tabName === 'courses') loadFacultyCourseSelector();
  else if (tabName === 'timetable') renderFacultyTimetable();
  else if (tabName === 'queries') renderFacultyQueries();
  else if (tabName === 'announcements') renderFacultyAnnouncements();
  else if (tabName === 'requests') renderFacultyRequestsHistory();
}

function renderFacultyWorkspace() {
  document.getElementById('faculty-banner-title').textContent = `Faculty Workspace — ${currentUser.name}`;
  document.getElementById('faculty-banner-sub').textContent = `${currentUser.designation} · ${currentUser.dept} Department`;

  switchFacultyTab('courses');
  updateFacultyQueryBadge();
}

function updateFacultyQueryBadge() {
  const facultyEmail = currentUser.email.toLowerCase();
  const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
  const myCourseIds = myCourses.map(c => c.id);

  const openQueries = store.getStudentQueries().filter(q => myCourseIds.includes(q.courseId) && q.status === 'OPEN').length;
  const badge = document.getElementById('badge-faculty-queries');
  if (badge) badge.textContent = openQueries;
}

// 1. My Courses & Students
function loadFacultyCourseSelector() {
  const select = document.getElementById('faculty-course-dropdown');
  const facultyEmail = currentUser.email.toLowerCase();
  const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);

  if (myCourses.length === 0) {
    select.innerHTML = `<option value="">No courses assigned</option>`;
    document.getElementById('faculty-course-stats-strip').innerHTML = `<p style="color:var(--text-secondary);">No courses assigned. Contact Super Admin (${SUPER_ADMIN_EMAIL}).</p>`;
    document.getElementById('faculty-roster-tbody').innerHTML = `<tr><td colspan="6" style="text-align:center; padding:2rem;">No courses assigned.</td></tr>`;
    return;
  }

  select.innerHTML = myCourses.map(c => `
    <option value="${c.id}">${c.code} — ${c.title} (Slot ${c.slot})</option>
  `).join('');

  loadFacultyCourseRoster();
}

function loadFacultyCourseRoster() {
  const courseId = document.getElementById('faculty-course-dropdown').value;
  const course = store.getCourses().find(c => c.id === courseId);
  if (!course) return;

  const statsStrip = document.getElementById('faculty-course-stats-strip');
  statsStrip.innerHTML = `
    <div>
      <div class="ribbon-label">Course Title</div>
      <div class="ribbon-val" style="color:var(--system-blue);">${course.code}: ${course.title}</div>
    </div>
    <div>
      <div class="ribbon-label">Slot &amp; Venue</div>
      <div class="ribbon-val"><span class="tag-slot">${course.day || 'MON'} Slot ${course.slot}</span> <span class="tag-room">${course.room}</span></div>
    </div>
    <div>
      <div class="ribbon-label">Credits</div>
      <div class="ribbon-val">${course.credits} Credits</div>
    </div>
    <div>
      <div class="ribbon-label">Enrolled Students</div>
      <div class="ribbon-val" style="color:var(--system-green);">${course.enrolledCount} Students</div>
    </div>
  `;

  renderRosterTable(courseId);
}

function renderRosterTable(courseId) {
  const tbody = document.getElementById('faculty-roster-tbody');
  const search = (document.getElementById('roster-search-box').value || '').toLowerCase();
  let students = store.getEnrolledStudents(courseId);

  if (search) {
    students = students.filter(s =>
      s.roll.toLowerCase().includes(search) ||
      s.name.toLowerCase().includes(search) ||
      s.batch.toLowerCase().includes(search)
    );
  }

  document.getElementById('roster-total-text').textContent = `Showing ${students.length} enrolled students`;

  if (students.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; color:var(--text-muted); padding:2rem;">No students enrolled yet.</td></tr>`;
    return;
  }

  tbody.innerHTML = students.map(s => {
    const attClass = s.attendance >= 85 ? 'att-good' : (s.attendance >= 75 ? 'att-avg' : 'att-low');
    return `
      <tr>
        <td><strong style="font-family:monospace; color:var(--system-blue);">${escapeHtml(s.roll)}</strong></td>
        <td><strong>${escapeHtml(s.name)}</strong></td>
        <td>${escapeHtml(s.batch)}</td>
        <td><span style="font-size:0.8rem; color:var(--text-muted);">${escapeHtml(s.email)}</span></td>
        <td><span class="attendance-pill ${attClass}">${s.attendance}%</span></td>
        <td style="text-align: right;"><span class="status-pill active">${s.status}</span></td>
      </tr>
    `;
  }).join('');
}

function filterRosterTable() {
  const courseId = document.getElementById('faculty-course-dropdown').value;
  renderRosterTable(courseId);
}

function exportRosterCSV() {
  const courseId = document.getElementById('faculty-course-dropdown').value;
  const course = store.getCourses().find(c => c.id === courseId);
  const students = store.getEnrolledStudents(courseId);

  if (!course || students.length === 0) {
    showToast('No student roster to export', 'error');
    return;
  }

  let csv = 'Roll Number,Student Name,Batch,Email,Attendance,Status\n';
  students.forEach(s => {
    csv += `"${s.roll}","${s.name}","${s.batch}","${s.email}",${s.attendance}%,"${s.status}"\n`;
  });

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Student_Roster_${course.code}.csv`;
  a.click();
  showToast(`Exported roster for ${course.code}`, 'success');
}

// 2. Faculty Timetable
function renderFacultyTimetable() {
  const tbody = document.getElementById('faculty-tt-tbody');
  const facultyEmail = currentUser.email.toLowerCase();
  const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
  const myCourseCodes = myCourses.map(c => c.code.toLowerCase());

  let myEntries = store.getTimetable().filter(t =>
    myCourseCodes.includes((t.course_code || '').toLowerCase()) ||
    (t.instructor || '').toLowerCase().includes(currentUser.name.toLowerCase())
  );

  tbody.innerHTML = myEntries.map(t => `
    <tr>
      <td><strong>${t.day}</strong></td>
      <td><span class="tag-slot">Slot ${t.slot}</span></td>
      <td><span style="font-family:monospace; font-weight:600;">${t.start_time} - ${t.end_time}</span></td>
      <td>
        <strong style="color:var(--system-blue);">${escapeHtml(t.course_code || '')}</strong>: ${escapeHtml(t.subject)}
      </td>
      <td><span class="tag-room">${escapeHtml(t.room || 'LH-101')}</span></td>
      <td style="text-align: right;"><span style="font-size:0.8rem; color:var(--text-secondary);">${escapeHtml(t.program || 'B.Tech')}</span></td>
    </tr>
  `).join('');
}

// 3. Faculty Queries
function renderFacultyQueries() {
  const container = document.getElementById('faculty-queries-stack');
  const facultyEmail = currentUser.email.toLowerCase();
  const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
  const myCourseIds = myCourses.map(c => c.id);

  const queries = store.getStudentQueries().filter(q => myCourseIds.includes(q.courseId) || myCourses.some(c => c.code === q.courseCode));

  if (queries.length === 0) {
    container.innerHTML = `<p style="color:var(--text-secondary); text-align:center; padding:2rem;">No student queries.</p>`;
    return;
  }

  container.innerHTML = queries.map(q => `
    <div class="item-surface-card">
      <div class="item-head">
        <div style="display:flex; align-items:center; gap:0.5rem;">
          <span class="tag-slot">${escapeHtml(q.courseCode)}</span>
          <strong>${escapeHtml(q.studentName)} (${escapeHtml(q.studentRoll)})</strong>
        </div>
        <span class="status-pill ${q.status === 'RESOLVED' ? 'approved' : 'pending'}">${q.status}</span>
      </div>

      <div class="quote-box-ios">
        <p class="quote-message">${escapeHtml(q.question)}</p>
      </div>

      ${q.response ? `
        <div class="reply-container">
          <strong>Your Reply:</strong> ${escapeHtml(q.response)}
        </div>
      ` : `
        <div style="margin-top:0.5rem;">
          <button class="btn-sm-primary" onclick="openReplyModal('${q.id}')">Reply to Student</button>
        </div>
      `}

      <div class="item-foot">
        <span>Sent: ${q.timestamp}</span>
        ${q.resolvedAt ? `<span>Resolved: ${q.resolvedAt}</span>` : ''}
      </div>
    </div>
  `).join('');
}

function openReplyModal(queryId) {
  const q = store.getStudentQueries().find(item => item.id === queryId);
  if (!q) return;

  document.getElementById('reply-query-id').value = q.id;
  document.getElementById('reply-student-name').textContent = q.studentName;
  document.getElementById('reply-student-roll').textContent = q.studentRoll;
  document.getElementById('reply-course-name').textContent = q.courseCode;
  document.getElementById('reply-question-text').textContent = q.question;
  document.getElementById('reply-response-text').value = '';

  openModal('modal-reply-query');
}

function handleSendQueryReply(e) {
  e.preventDefault();
  const queryId = document.getElementById('reply-query-id').value;
  const reply = document.getElementById('reply-response-text').value.trim();

  if (store.replyQuery(queryId, reply)) {
    showToast('Reply sent to student!', 'success');
    closeModal('modal-reply-query');
    renderFacultyQueries();
    updateFacultyQueryBadge();
  }
}

// 4. Course Announcements
function renderFacultyAnnouncements() {
  const container = document.getElementById('faculty-announcements-stack');
  const facultyEmail = currentUser.email.toLowerCase();
  const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
  const myCourseIds = myCourses.map(c => c.id);

  const announcements = store.getCourseAnnouncements().filter(a => myCourseIds.includes(a.courseId) || myCourses.some(c => c.code === a.courseCode));

  if (announcements.length === 0) {
    container.innerHTML = `<p style="color:var(--text-secondary); text-align:center; padding:2rem;">No course notices posted yet.</p>`;
    return;
  }

  container.innerHTML = announcements.map(a => `
    <div class="item-surface-card">
      <div class="item-head">
        <div style="display:flex; align-items:center; gap:0.5rem;">
          <span class="tag-slot">${escapeHtml(a.courseCode)}</span>
          <strong style="font-size:1.05rem;">${escapeHtml(a.title)}</strong>
        </div>
        <span class="status-pill active">Published</span>
      </div>
      <div class="item-text">${escapeHtml(a.body)}</div>
      <div class="item-foot">
        <span>By: <strong>${escapeHtml(a.facultyName)}</strong></span>
        <span>${a.createdAt}</span>
      </div>
    </div>
  `).join('');
}

function handleSaveFacultyAnnouncement(e) {
  e.preventDefault();
  const courseId = document.getElementById('fac-ann-course').value;
  const title = document.getElementById('fac-ann-title').value.trim();
  const body = document.getElementById('fac-ann-body').value.trim();

  const course = store.getCourses().find(c => c.id === courseId);
  if (!course) return;

  store.saveCourseAnnouncement({
    courseId: course.id,
    courseCode: course.code,
    facultyName: currentUser.name,
    title,
    body
  });

  showToast(`Notice published for ${course.code} students!`, 'success');
  closeModal('modal-post-course-announcement');
  renderFacultyAnnouncements();
}

// 5. Raise Slot Change Request
function updateSlotReqCurrentSlot() {
  const courseId = document.getElementById('slot-req-course').value;
  const course = store.getCourses().find(c => c.id === courseId);
  const input = document.getElementById('slot-req-current-slot');
  if (course) {
    input.value = `${course.day || 'MON'} Slot ${course.slot} (${course.time || '08:00 - 08:50'})`;
  }
}

function handleRaiseSlotRequest(e) {
  e.preventDefault();
  const courseId = document.getElementById('slot-req-course').value;
  const targetDay = document.getElementById('slot-req-target-day').value;
  const targetSlot = document.getElementById('slot-req-target-slot').value;
  const targetRoom = document.getElementById('slot-req-target-room').value.trim();
  const reason = document.getElementById('slot-req-reason').value.trim();

  const course = store.getCourses().find(c => c.id === courseId);
  if (!course) return;

  store.raiseSlotRequest({
    courseId: course.id,
    courseCode: course.code,
    courseTitle: course.title,
    facultyEmail: currentUser.email,
    facultyName: currentUser.name,
    currentDay: course.day || 'MONDAY',
    currentSlot: `Slot ${course.slot} (${course.time || '08:00'})`,
    targetDay,
    targetSlot: `Slot ${targetSlot}`,
    targetRoom,
    reason
  });

  showToast('Slot change request submitted to Super Admin!', 'success');
  closeModal('modal-raise-slot-request');
  renderFacultyRequestsHistory();
  switchFacultyTab('requests');
}

function renderFacultyRequestsHistory() {
  const tbody = document.getElementById('faculty-requests-tbody');
  const facultyEmail = currentUser.email.toLowerCase();
  const requests = store.getSlotRequests().filter(r => r.facultyEmail.toLowerCase() === facultyEmail);

  tbody.innerHTML = requests.map(r => `
    <tr>
      <td><strong>${escapeHtml(r.courseCode)}: ${escapeHtml(r.courseTitle)}</strong></td>
      <td><span style="color:var(--system-red);">${r.currentDay} ${r.currentSlot}</span></td>
      <td><span style="color:var(--system-green); font-weight:700;">${r.targetDay} ${r.targetSlot} (${r.targetRoom})</span></td>
      <td style="font-size:0.85rem; color:var(--text-secondary);">${escapeHtml(r.reason)}</td>
      <td style="font-size:0.8rem; color:var(--text-muted);">${r.createdAt}</td>
      <td style="text-align: right;"><span class="status-pill ${r.status.toLowerCase()}">${r.status}</span></td>
    </tr>
  `).join('');
}


