// =========================================================================
// MODALS & TOAST UTILITIES
// =========================================================================

function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (!modal) return;

  if (modalId === 'modal-add-course') {
    const select = document.getElementById('course-faculty-email');
    const faculties = store.getMembers().filter(m => m.role === 'faculty');
    select.innerHTML = faculties.map(f => `<option value="${f.email}">${f.name} (${f.email})</option>`).join('');
  } else if (modalId === 'modal-raise-slot-request') {
    const select = document.getElementById('slot-req-course');
    const facultyEmail = currentUser.email.toLowerCase();
    const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
    select.innerHTML = myCourses.map(c => `<option value="${c.id}">${c.code} - ${c.title}</option>`).join('');
    updateSlotReqCurrentSlot();
  } else if (modalId === 'modal-post-course-announcement') {
    const select = document.getElementById('fac-ann-course');
    const facultyEmail = currentUser.email.toLowerCase();
    const myCourses = store.getCourses().filter(c => c.facultyEmail.toLowerCase() === facultyEmail);
    select.innerHTML = myCourses.map(c => `<option value="${c.id}">${c.code} - ${c.title}</option>`).join('');
  }

  modal.style.display = 'flex';
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.style.display = 'none';
}

window.addEventListener('click', (e) => {
  if (e.target.classList.contains('modal-backdrop')) {
    e.target.style.display = 'none';
  }
});

function showToast(message, type = 'success') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const iconSvg = type === 'success'
    ? `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>`
    : `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`;

  const toast = document.createElement('div');
  toast.className = `toast-item ${type}`;
  toast.innerHTML = `
    <span class="toast-icon">${iconSvg}</span>
    <span>${escapeHtml(message)}</span>
  `;

  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transition = 'opacity 0.3s ease';
    setTimeout(() => toast.remove(), 300);
  }, 3200);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
